function roomsOverlap(a, b) {
  return a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
}
function corridor(from, to) {
  let x = from[0], y = from[1];
  const tiles = [[x, y]];
  while (x !== to[0]) { x += Math.sign(to[0] - x); tiles.push([x, y]); }
  while (y !== to[1]) { y += Math.sign(to[1] - y); tiles.push([x, y]); }
  return tiles;
}
function dungeon(seed, w, h) {
  const rand = mulberry32(seed);
  const rooms = [];
  for (let i = 0; i < 30; i++) {
    const rw = randInt(rand, 3, 6);
    const rh = randInt(rand, 3, 5);
    const x = randInt(rand, 1, w - rw - 1);
    const y = randInt(rand, 1, h - rh - 1);
    const room = { x, y, w: rw, h: rh };
    if (!rooms.some(r => roomsOverlap(room, { x: r.x - 1, y: r.y - 1, w: r.w + 2, h: r.h + 2 }))) rooms.push(room);
  }
  const grid = [];
  for (let y = 0; y < h; y++) grid.push(new Array(w).fill("#"));
  for (const r of rooms) {
    for (let y = r.y; y < r.y + r.h; y++) {
      for (let x = r.x; x < r.x + r.w; x++) grid[y][x] = ".";
    }
  }
  const centres = rooms.map(r => [r.x + Math.floor(r.w / 2), r.y + Math.floor(r.h / 2)]);
  for (let i = 1; i < centres.length; i++) {
    for (const [x, y] of corridor(centres[i - 1], centres[i])) grid[y][x] = ".";
  }
  const map = grid.map(row => row.join(""));
  const floor = map.join("").split(".").length - 1;
  return { rooms: rooms.length, floor, start: centres[0], exit: centres[centres.length - 1], map };
}

